#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Contraptions;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Grids;
using PVZEngine.Models;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.teleporter)]
    public class Teleporter : EntityBehaviourDefinition
    {
        public Teleporter(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            entity.SetAnimationBool("Signal", entity.IsEvoked());
        }
        public static void Teleport(Entity entity, LawnGrid lawnGrid)
        {
            foreach (var gridEntity in lawnGrid.GetEntities())
            {
                if (gridEntity.NoTeleporter())
                    continue;
                var gridPositionOffset = gridEntity.Position - lawnGrid.GetEntityPosition();
                var buff = gridEntity.AddBuff<TeleporterTeleportUpBuff>();
                TeleporterTeleportUpBuff.SetTargetPosition(buff, entity.Position + gridPositionOffset);
            }
            entity.AddBuff<TeleporterTriggeredBuff>();
            entity.PlaySound(VanillaSoundID.teleportUp);
        }
    }
}
